<?php
require_once __DIR__.'/core.php';tt_require_login();$db=tt_db_open(true);$q=trim((string)($_GET['q']??$_POST['q']??''));$selected=trim((string)($_GET['user']??''));$like='%'.$q.'%';if($q!==''){$s=tt_prepare($db,'SELECT `id`,`username`,`aboutcontent`,`tags`,`created_at`,`last_login_at` FROM `accounts` WHERE `username` LIKE ? OR `aboutcontent` LIKE ? OR `tags` LIKE ? ORDER BY `username` LIMIT 100');$s->bind_param('sss',$like,$like,$like);}else{$s=tt_prepare($db,'SELECT `id`,`username`,`aboutcontent`,`tags`,`created_at`,`last_login_at` FROM `accounts` ORDER BY `username` LIMIT 100');}$s->execute();$users=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();$posts=[];if($selected!==''){[$vis,$params,$types]=tt_visible_where('p');$sql='SELECT p.`id`,p.`title`,p.`content`,p.`dt`,p.`tags`,p.`type`,p.`scope` FROM `posts` p WHERE '.$vis.' AND p.`name`=? ORDER BY p.`dt` DESC LIMIT 50';$params[]=$selected;$types.='s';$s=tt_prepare($db,$sql);$s->bind_param($types,...$params);$s->execute();$posts=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();}$db->close();
?><!doctype html><html class="tabletime"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.php"><title>Tabletime · People</title></head><body><?php tt_nav('profile.php');?><main class="content"><h2>People</h2><form class="searchbar" method="get"><input name="q" value="<?=tt_h($q)?>" placeholder="Search users, descriptions, tags"><input type="submit" value="Search"></form><section class="grid"><?php foreach($users as $u):?><article class="card"><h3><a href="profile.php?user=<?=urlencode($u['username'])?>"><?=tt_h($u['username'])?></a></h3><p><?=nl2br(tt_h($u['aboutcontent']))?></p><p class="meta"><?=tt_h($u['tags'])?></p><?php if($u['username']!==($_SESSION['name']??'')):?><p><a href="friend.php?user=<?=urlencode($u['username'])?>">Friend controls</a></p><?php endif;?></article><?php endforeach;?></section><?php if($selected!==''):?><h2>Posts by <?=tt_h($selected)?></h2><section class="grid"><?php foreach($posts as $p):?><article class="card"><h3><?=tt_h($p['title'])?></h3><p class="meta"><?=tt_h($p['dt'])?> · <?=tt_h($p['type'])?> · <?=tt_h(trim($p['scope']))?></p><p><?=nl2br(tt_h($p['content']))?></p></article><?php endforeach;?><?php if(!$posts):?><article class="card">No visible posts.</article><?php endif;?></section><?php endif;?></main></body></html>